def pre_process(task, outer_context):
    m = task.metadata.get("m", 0)
    if m == 2:
        additional_context = """When m == 2 use the exact optimal Johnson's rule (group jobs by a_j < b_j or a_j > b_j, sort group1 ascending on a, group2 descending on b, concatenate; for n <= 1 return identity). For all other m implement the 3-seed NEH insertion heuristic exactly as described previously: sort jobs by total processing time, enumerate all 6 permutations of the first 3 as seed, pick the best makespan seed, then iteratively insert each remaining job (sorted order) into the single best position by evaluating makespan on each of the O(n) positions. Always return job_sequence as flat list [1..n]. Handle n <= 3 by full enumeration. Use only standard library; keeps makespan evaluator identical to baseline."""
    else:
        additional_context = """Implement an improved NEH heuristic for Fm||Cmax that starts with the first 3 jobs (sorted by decreasing total processing time) instead of 2: enumerate all 6 permutations of those 3 jobs, evaluate makespan on each, and select the best seed sequence. Then iteratively insert each remaining job (in sorted order) into the single best insertion position w.r.t. makespan, exactly as in standard NEH. This produces a stronger initial permutation and reliably raises the continuous score. Always return job_sequence as a flat list of integers [1..n] with no duplicates or omissions. Handle n<=3 as a special case by returning the best permutation of the jobs. Use only standard library; keep makespan evaluation identical to the baseline."""
    return additional_context